-- ===========================================================================
--  The Purple Cup - SQL Analysis Layer
-- ===========================================================================
--  SIMULATED / SYNTHETIC DATA - PORTFOLIO PROJECT.
--  These queries run against data/brewmetrics.db, which is generated by
--  data_generation/generate_data.py. Every number is invented for
--  demonstration; the SQL and the analysis are real.
--
--  Author: Erica Mathias
--
--  The database has four tables:
--    products (product_id, sku, name, category, price)
--    customers(customer_id, signup_date, region)
--    campaigns(campaign_id, name, channel, start_date, end_date, spend,
--              impressions)          <- impressions live here (top of funnel)
--    events   (event_id, customer_id, campaign_id, product_id, event_type,
--              timestamp, revenue)   <- one row per click / add_to_cart /
--                                       purchase (the fact table)
--
--  Each query below is preceded by the BUSINESS QUESTION it answers and the
--  SQL techniques it demonstrates.
-- ===========================================================================


-- ===========================================================================
--  QUERY 1 - THE MARKETING FUNNEL, with stage-to-stage conversion rates
-- ---------------------------------------------------------------------------
--  Business question: "Of everyone we reached, how many made it to each next
--  stage - and where do we lose the most people?"
--
--  Techniques: CTE (WITH), UNION ALL to assemble the funnel, and two WINDOW
--  functions - LAG() to reach the previous stage's count, and FIRST_VALUE()
--  to compare every stage back to impressions.
--
--  Note on shape: impressions are a SUM over the campaigns table; the other
--  three stages are COUNTs over the events log (see header).
-- ===========================================================================
WITH funnel(stage, stage_order, cnt) AS (
    SELECT 'Impressions', 1, (SELECT SUM(impressions) FROM campaigns)
    UNION ALL
    SELECT 'Clicks',      2, (SELECT COUNT(*) FROM events WHERE event_type = 'click')
    UNION ALL
    SELECT 'Add to cart', 3, (SELECT COUNT(*) FROM events WHERE event_type = 'add_to_cart')
    UNION ALL
    SELECT 'Purchase',    4, (SELECT COUNT(*) FROM events WHERE event_type = 'purchase')
)
SELECT
    stage,
    cnt AS count,
    -- Conversion from the PREVIOUS stage: this row's count / prior row's count.
    -- LAG(cnt) fetches the count from the row one position back (by stage_order).
    ROUND(100.0 * cnt / LAG(cnt) OVER (ORDER BY stage_order), 2) AS step_conv_pct,
    -- How much of the very top of the funnel survives to this stage.
    ROUND(100.0 * cnt / FIRST_VALUE(cnt) OVER (ORDER BY stage_order), 4) AS pct_of_impressions
FROM funnel
ORDER BY stage_order;


-- ===========================================================================
--  QUERY 2 - CHANNEL PERFORMANCE: clicks, purchases, revenue, spend, ROAS
-- ---------------------------------------------------------------------------
--  Business question: "Which channels actually pay for themselves?"
--
--  Techniques: two CTEs, a JOIN, GROUP BY, and a WINDOW function
--  (SUM() OVER ()) to show each channel's share of total revenue.
--
--  Why two CTEs: revenue/clicks come from the events log, but spend and
--  impressions live once per campaign. Aggregating them separately first
--  avoids double-counting spend across a campaign's many event rows - a
--  classic JOIN fan-out trap worth being able to explain.
-- ===========================================================================
WITH channel_events AS (
    SELECT
        c.channel,
        SUM(e.event_type = 'click')          AS clicks,
        SUM(e.event_type = 'purchase')       AS purchases,
        SUM(CASE WHEN e.event_type = 'purchase' THEN e.revenue ELSE 0 END) AS revenue
    FROM events   AS e
    JOIN campaigns AS c ON c.campaign_id = e.campaign_id
    GROUP BY c.channel
),
channel_budget AS (
    SELECT channel,
           SUM(spend)       AS spend,
           SUM(impressions) AS impressions
    FROM campaigns
    GROUP BY channel
)
SELECT
    b.channel,
    b.impressions,
    ev.clicks,
    ev.purchases,
    ROUND(ev.revenue, 2)                       AS revenue,
    b.spend,
    ROUND(ev.revenue * 1.0 / b.spend, 2)       AS roas,          -- $ back per $1 spent
    ROUND(100.0 * ev.purchases / ev.clicks, 2) AS click_to_buy_pct,
    -- Revenue share across ALL channels (window over the whole result set).
    ROUND(100.0 * ev.revenue / SUM(ev.revenue) OVER (), 1) AS pct_of_total_revenue
FROM channel_budget  AS b
JOIN channel_events  AS ev ON ev.channel = b.channel
ORDER BY roas DESC;


-- ===========================================================================
--  QUERY 3 - TOP CAMPAIGNS BY REVENUE, ranked
-- ---------------------------------------------------------------------------
--  Business question: "Which individual campaigns drove the most revenue,
--  and how efficient was each?"
--
--  Techniques: LEFT JOIN (keep every campaign even if it had zero purchases),
--  GROUP BY, and the RANK() WINDOW function to number campaigns by revenue.
-- ===========================================================================
SELECT
    RANK() OVER (ORDER BY SUM(CASE WHEN e.event_type = 'purchase' THEN e.revenue ELSE 0 END) DESC) AS revenue_rank,
    c.name,
    c.channel,
    SUM(e.event_type = 'purchase')                                              AS purchases,
    ROUND(SUM(CASE WHEN e.event_type = 'purchase' THEN e.revenue ELSE 0 END), 2) AS revenue,
    c.spend,
    ROUND(SUM(CASE WHEN e.event_type = 'purchase' THEN e.revenue ELSE 0 END) * 1.0 / c.spend, 2) AS roas
FROM campaigns AS c
LEFT JOIN events AS e ON e.campaign_id = c.campaign_id
GROUP BY c.campaign_id, c.name, c.channel, c.spend
ORDER BY revenue DESC;


-- ===========================================================================
--  QUERY 4 - MONTHLY REVENUE TREND with a running (cumulative) total
-- ---------------------------------------------------------------------------
--  Business question: "How did revenue build month over month across the
--  6-month period?"
--
--  Techniques: a CTE to bucket purchases by month (strftime on the
--  timestamp), then a running-total WINDOW function
--  (SUM(...) OVER (ORDER BY month)) - the cumulative revenue to date.
-- ===========================================================================
WITH monthly AS (
    SELECT
        strftime('%Y-%m', timestamp)   AS month,
        SUM(revenue)                   AS revenue,
        COUNT(*)                       AS orders
    FROM events
    WHERE event_type = 'purchase'
    GROUP BY month
)
SELECT
    month,
    orders,
    ROUND(revenue, 2)                                    AS revenue,
    ROUND(SUM(revenue) OVER (ORDER BY month), 2)         AS cumulative_revenue
FROM monthly
ORDER BY month;


-- ===========================================================================
--  QUERY 5 - TOP PRODUCTS BY REVENUE (bonus: a JOIN into the catalog)
-- ---------------------------------------------------------------------------
--  Business question: "Which SKUs actually drive the money?"
--  Techniques: JOIN events -> products, GROUP BY, ORDER BY ... LIMIT.
-- ===========================================================================
SELECT
    p.name,
    p.category,
    p.price,
    SUM(e.event_type = 'purchase')            AS units_orders,
    ROUND(SUM(e.revenue), 2)                  AS revenue
FROM events   AS e
JOIN products AS p ON p.product_id = e.product_id
WHERE e.event_type = 'purchase'
GROUP BY p.product_id, p.name, p.category, p.price
ORDER BY revenue DESC
LIMIT 10;
